package com.ebuddy.security;
import com.ebuddy.repo.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.UUID;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((r,s,x)->{s.setStatus(401);s.setContentType("application/json");s.getWriter().write("{\"error\":\"authentication_failed\",\"code\":\"AUTH_REQUIRED\",\"message\":\"Authentication required\",\"retryable\":false}");}).accessDeniedHandler((r,s,x)->{s.setStatus(403);s.setContentType("application/json");s.getWriter().write("{\"error\":\"forbidden\",\"code\":\"FORBIDDEN\",\"message\":\"Operation is not permitted\",\"retryable\":false}");})).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/j2me/login","/api/j2me/register","/actuator/health","/v1/ws/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} }
@Component class JwtFilter extends OncePerRequestFilter { final JwtService jwt; JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws IOException,ServletException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{UUID u=jwt.subject(h.substring(7));var a=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(u,null,java.util.List.of());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(RuntimeException ignored){} c.doFilter(r,s);} }
